mapper.select:
/* PatientReportMapper.getPatientListStatistics */ with cte_panels as ( select 1 as row_no , 'COMPREHENSIVE_PANEL' as test_classification , 'HPV_STI' as disease , 'Human Papillomavirus Infections + Sexually Transmitted Infections' as disease_name , 'RTI' as panel_code , 'HPV + STI Comprehensive Panel' as panel_name , 10 as detected_analytes_count , 0 as print_count union all select 2 as row_no , 'COMPREHENSIVE_PANEL' as test_classification , 'RP' as disease , 'Respiratory Tract Infections' as disease_name , 'ABI' as panel_code , 'Respiratory Comprehensive Panel' as panel_name , 4 as detected_analytes_count , 2 as print_count union all select 3 as row_no , 'COMPREHENSIVE_PANEL' as test_classification , 'GI' as disease , 'Gastrointestinal Infections' as disease_name , 'GTI' as panel_code , 'Gastrointestinal Comprehensive Panel' as panel_name , 10 as detected_analytes_count , 0 as print_count union all select 4 as row_no , 'COMPREHENSIVE_PANEL' as test_classification , 'HPV_STI' as disease , 'Human Papillomavirus Infections + Sexually Transmitted Infections' as disease_name , 'RTI' as panel_code , 'HPV + STI Comprehensive Panel' as panel_name , 4 as detected_analytes_count , 2 as print_count union all select 5 as row_no , 'COMPREHENSIVE_PANEL' as test_classification , 'RP' as disease , 'Respiratory Tract Infections' as disease_name , 'ABI' as panel_code , 'Respiratory Comprehensive Panel' as panel_name , 10 as detected_analytes_count , 0 as print_count union all select 6 as row_no , 'OTHER_PANELS' as test_classification , 'OTHERS' as disease , 'Other Diseases' as disease_name , 'N_TEV' as panel_code , 'Other Pathogens Detection' as panel_name , 4 as detected_analytes_count , 0 as print_count union all select 7 as row_no , 'OTHER_PANELS' as test_classification , 'HPV' as disease , 'Human Papillomavirus Infections' as disease_name , 'N2_HR' as panel_code , 'Novaplex II HPV28 Detection' as panel_name , 10 as detected_analytes_count , 0 as print_count union all select 8 as row_no , 'OTHER_PANELS' as test_classification , 'HPV' as disease , 'Human Papillomavirus Infections' as disease_name , 'N2_HPV28' as panel_code , 'Novaplex II HPV28 Detection' as panel_name , 4 as detected_analytes_count , 0 as print_count union all select 9 as row_no , 'OTHER_PANELS' as test_classification , 'RP' as disease , 'Respiratory Tract Infections' as disease_name , 'RP1+RP2' as panel_code , 'Respiratory Panel 1 + 2' as panel_name , 10 as detected_analytes_count , 0 as print_count union all select 10 as row_no , 'OTHER_PANELS' as test_classification , 'RP' as disease , 'Respiratory Tract Infections' as disease_name , 'RP1+RP2+RP3+RP4' as panel_code , 'Respiratory Panel 1 + 2 + 3 + 4' as panel_name , 4 as detected_analytes_count , 0 as print_count ) , cte_reports as ( select md5(b.batch_no::text || '-' || a.row_no::text)::uuid::text as report_id , 'S26-1015-' || lpad((231 + b.batch_no)::text, 4, '0') as sample_id , a.test_classification , a.disease , a.disease_name , a.panel_code , a.panel_name , current_date - (b.batch_no * 3 + a.row_no - 1) as test_date , a.detected_analytes_count , current_date - (b.batch_no * 3 + a.row_no - 1) as report_created_date , a.print_count , case when a.print_count = 0 then null::timestamp else (current_date - (b.batch_no * 3 + a.row_no - 1))::timestamp end as last_printed_at from cte_panels as a cross join generate_series(0, 12) as b(batch_no) )
, cte_input_samples as ( select unnest(array[
#{sampleId}
]::text[]) as sample_id )
, cte_samples as ( select 'S26-1015-' || lpad(a.sample_no::text, 4, '0') as sample_id from generate_series(231, 244) as a(sample_no) ) , cte_filtered as ( select a.* from cte_reports as a where a.test_date <= current_date
and a.sample_id in ( select z.sample_id from cte_input_samples as z )
and a.test_classification = #{testClassification}
and a.disease = #{disease}
and a.test_date >= current_date
and a.test_date >= current_date - 6
and a.test_date >= current_date - interval '1 month'
) select count(1) as report_count , count(distinct a.sample_id) as found_sample_id_count
, ( select count(1) from cte_samples as x where x.sample_id in ( select z.sample_id from cte_input_samples as z ) and not exists ( select 1 from cte_filtered as y where y.sample_id = x.sample_id ) ) as no_results_count , ( select count(1) from cte_input_samples as x where not exists ( select 1 from cte_samples as y where y.sample_id = x.sample_id ) ) as not_found_count
, 0::bigint as no_results_count , 0::bigint as not_found_count
from cte_filtered as a

/* PatientReportMapper.getPatientList */ with cte_panels as ( select 1 as row_no , 'COMPREHENSIVE_PANEL' as test_classification , 'HPV_STI' as disease , 'Human Papillomavirus Infections + Sexually Transmitted Infections' as disease_name , 'RTI' as panel_code , 'HPV + STI Comprehensive Panel' as panel_name , 10 as detected_analytes_count , 0 as print_count union all select 2 as row_no , 'COMPREHENSIVE_PANEL' as test_classification , 'RP' as disease , 'Respiratory Tract Infections' as disease_name , 'ABI' as panel_code , 'Respiratory Comprehensive Panel' as panel_name , 4 as detected_analytes_count , 2 as print_count union all select 3 as row_no , 'COMPREHENSIVE_PANEL' as test_classification , 'GI' as disease , 'Gastrointestinal Infections' as disease_name , 'GTI' as panel_code , 'Gastrointestinal Comprehensive Panel' as panel_name , 10 as detected_analytes_count , 0 as print_count union all select 4 as row_no , 'COMPREHENSIVE_PANEL' as test_classification , 'HPV_STI' as disease , 'Human Papillomavirus Infections + Sexually Transmitted Infections' as disease_name , 'RTI' as panel_code , 'HPV + STI Comprehensive Panel' as panel_name , 4 as detected_analytes_count , 2 as print_count union all select 5 as row_no , 'COMPREHENSIVE_PANEL' as test_classification , 'RP' as disease , 'Respiratory Tract Infections' as disease_name , 'ABI' as panel_code , 'Respiratory Comprehensive Panel' as panel_name , 10 as detected_analytes_count , 0 as print_count union all select 6 as row_no , 'OTHER_PANELS' as test_classification , 'OTHERS' as disease , 'Other Diseases' as disease_name , 'N_TEV' as panel_code , 'Other Pathogens Detection' as panel_name , 4 as detected_analytes_count , 0 as print_count union all select 7 as row_no , 'OTHER_PANELS' as test_classification , 'HPV' as disease , 'Human Papillomavirus Infections' as disease_name , 'N2_HR' as panel_code , 'Novaplex II HPV28 Detection' as panel_name , 10 as detected_analytes_count , 0 as print_count union all select 8 as row_no , 'OTHER_PANELS' as test_classification , 'HPV' as disease , 'Human Papillomavirus Infections' as disease_name , 'N2_HPV28' as panel_code , 'Novaplex II HPV28 Detection' as panel_name , 4 as detected_analytes_count , 0 as print_count union all select 9 as row_no , 'OTHER_PANELS' as test_classification , 'RP' as disease , 'Respiratory Tract Infections' as disease_name , 'RP1+RP2' as panel_code , 'Respiratory Panel 1 + 2' as panel_name , 10 as detected_analytes_count , 0 as print_count union all select 10 as row_no , 'OTHER_PANELS' as test_classification , 'RP' as disease , 'Respiratory Tract Infections' as disease_name , 'RP1+RP2+RP3+RP4' as panel_code , 'Respiratory Panel 1 + 2 + 3 + 4' as panel_name , 4 as detected_analytes_count , 0 as print_count ) , cte_reports as ( select md5(b.batch_no::text || '-' || a.row_no::text)::uuid::text as report_id , 'S26-1015-' || lpad((231 + b.batch_no)::text, 4, '0') as sample_id , a.test_classification , a.disease , a.disease_name , a.panel_code , a.panel_name , current_date - (b.batch_no * 3 + a.row_no - 1) as test_date , a.detected_analytes_count , current_date - (b.batch_no * 3 + a.row_no - 1) as report_created_date , a.print_count , case when a.print_count = 0 then null::timestamp else (current_date - (b.batch_no * 3 + a.row_no - 1))::timestamp end as last_printed_at from cte_panels as a cross join generate_series(0, 12) as b(batch_no) )
, cte_input_samples as ( select unnest(array[
#{sampleId}
]::text[]) as sample_id )
select a.report_id , a.sample_id , a.test_classification , a.disease , a.disease_name , a.panel_code , a.panel_name , a.test_date , a.detected_analytes_count , a.report_created_date , a.print_count , a.last_printed_at from cte_reports as a where a.test_date <= current_date
and a.sample_id in ( select z.sample_id from cte_input_samples as z )
and a.test_classification = #{testClassification}
and a.disease = #{disease}
and a.test_date >= current_date
and a.test_date >= current_date - 6
and a.test_date >= current_date - interval '1 month'
order by a.test_date desc , a.sample_id , a.report_id limit #{size} offset ((#{page}::bigint - 1) * #{size})
